package io.github.projectopenubl.xhandler.clients;

import io.github.projectopenubl.xhandler.models.OseProvider;
import io.quarkus.narayana.jta.QuarkusTransaction;
import jakarta.enterprise.context.ApplicationScoped;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.UUID;
import org.jboss.logging.Logger;

/**
 * Who sends us documents to check (DESIGN.md §11.4 step 1; RS 117-2017 art. 7.9: web services
 * "con usuario y contraseña"). Passwords are generated by the platform (144 random bits), so they
 * can't be guessed: a salted SHA-256 is enough to store them, and there is no account lockout —
 * a lockout would let anyone who knows a username (RUCs are public) stop an issuer from
 * invoicing. Failures are counted and logged for monitoring; per-IP rate limits belong to the
 * gateway. Every login does the same work, known user or not.
 */
@ApplicationScoped
public class OseClients {

    public record Client(UUID id, String issuerRuc, String username, UUID tenantId) {}

    /** A refused login: SUNAT's code 0102 for the issuer, nothing about why. */
    public static final class Unauthorized extends RuntimeException {
        Unauthorized() {
            super("Usuario o contraseña incorrectos");
        }
    }

    /** Consecutive failures that get logged for the platform (a misconfigured client or an attack). */
    static final int ALERT_FAILURES = 20;
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final String DUMMY = "sha256$AAAAAAAAAAAAAAAAAAAAAA==$AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";

    private final OseProvider oseProvider;

    public OseClients(OseProvider oseProvider) {
        this.oseProvider = oseProvider;
    }

    public Client authenticate(String username, String password) {
        if (username == null || password == null || username.isBlank() || password.isEmpty() || username.length() > 100
                || password.length() > 200) {
            throw new Unauthorized();
        }
        OseProvider.ClientLogin r = QuarkusTransaction.requiringNew().call(() -> oseProvider.getClientLogin(username)).orElse(null);
        // Always one verification, whatever the user's state
        boolean matches = verify(password, r == null ? DUMMY : r.passwordHash());
        if (r == null) {
            throw new Unauthorized();
        }
        UUID id = r.id();
        if (!matches || !"active".equals(r.status())) {
            int failures = QuarkusTransaction.requiringNew().call(() -> oseProvider.countFailedLogin(id));
            if (failures % ALERT_FAILURES == 0) {
                Logger.getLogger("xhandler.audit.platform").warnf("OSE user %s has %d consecutive failed logins", username, failures);
            }
            throw new Unauthorized();
        }
        QuarkusTransaction.requiringNew().run(() -> oseProvider.markLogin(id));
        return new Client(id, r.issuerRuc(), r.username(), r.tenantId());
    }

    /** By username only: the SFTP server authenticated the user already. */
    public java.util.Optional<Client> byUsername(String username) {
        return QuarkusTransaction.requiringNew().call(() -> oseProvider.getActiveClient(username))
                .map(r -> new Client(r.id(), r.issuerRuc(), r.username(), r.tenantId()));
    }

    public static String newPassword() {
        byte[] raw = new byte[18];
        RANDOM.nextBytes(raw);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
    }

    public static String hash(String password) {
        byte[] salt = new byte[16];
        RANDOM.nextBytes(salt);
        return "sha256$" + Base64.getEncoder().encodeToString(salt) + "$" + Base64.getEncoder().encodeToString(digest(salt, password));
    }

    static boolean verify(String password, String stored) {
        String[] parts = stored.split("\\$");
        try {
            if (parts.length == 3 && "sha256".equals(parts[0])) {
                return MessageDigest.isEqual(Base64.getDecoder().decode(parts[2]), digest(Base64.getDecoder().decode(parts[1]), password));
            }
            if (parts.length == 4 && "pbkdf2".equals(parts[0])) {
                // Users created before the change
                javax.crypto.SecretKeyFactory factory = javax.crypto.SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
                byte[] actual = factory.generateSecret(new javax.crypto.spec.PBEKeySpec(password.toCharArray(), Base64.getDecoder().decode(parts[2]),
                        Integer.parseInt(parts[1]), 256)).getEncoded();
                return MessageDigest.isEqual(Base64.getDecoder().decode(parts[3]), actual);
            }
            return false;
        } catch (IllegalArgumentException | java.security.GeneralSecurityException e) {
            return false;
        }
    }

    private static byte[] digest(byte[] salt, String password) {
        try {
            MessageDigest sha = MessageDigest.getInstance("SHA-256");
            sha.update(salt);
            return sha.digest(password.getBytes(StandardCharsets.UTF_8));
        } catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}
